python3 -c "import csv,glob
seen={}
for f in sorted(glob.glob('/workspace/show_records_folder/shows_2025_0*.csv')):
  for r in csv.DictReader(open(f)):
    if 'cancelled' in r['memo'] or r['show_ref'] in seen: continue
    seen[r['show_ref']]=(r['performed_on'],r['venue'],r['city'])
open('/workspace/show_dates.txt','w').write('\n'.join(f'{v[0]}  {v[1]}, {v[2]}' for k,v in sorted(seen.items(),key=lambda x:x[1][0])))"

